SELECT CASE WHEN sqft >= 12852 THEN 'high' WHEN sqft >= 4069 THEN 'mid' ELSE 'low' END AS sqft_bucket, ROUND((100 * SUM(CASE WHEN city = 'Singapore' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_singapore, AVG(sqft) AS avg_sqft FROM stores GROUP BY 1 HAVING ROUND((100 * SUM(CASE WHEN city = 'Singapore' THEN 1 ELSE 0 END)) / COUNT(*), 1) < 26 ORDER BY 3 DESC, pct_singapore DESC, sqft_bucket LIMIT 20
